import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/sheets/connect-a-database-dialog.png",i="/docs/images/sheets/connect-a-database-results.png",k=JSON.parse('{"title":"Connect a database","description":"Run a SQL query against a PostgreSQL database and see the results in a read-only tab of your sheet.","frontmatter":{"title":"Connect a database","description":"Run a SQL query against a PostgreSQL database and see the results in a read-only tab of your sheet.","type":"how-to"},"headers":[],"relativePath":"sheets/connect-a-database.md","filePath":"sheets/connect-a-database.md"}'),r={name:"sheets/connect-a-database.md"};function l(c,e,d,h,u,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="connect-a-database" tabindex="-1">Connect a database <a class="header-anchor" href="#connect-a-database" aria-label="Permalink to &quot;Connect a database&quot;">​</a></h1><p>Run a SQL query against a PostgreSQL database and see the results in a read-only tab of your sheet.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Connections are shared with the workspace. Every member queries with the credentials you save, so use a read-only account.</li><li>Queries must be a single <code>SELECT</code> or <code>WITH</code> statement. Results stop at 10,000 rows, and a query stops after 30 seconds.</li><li>Only workspace members can run a query. On a share link you see the saved query but can&#39;t run it.</li></ul></div><h2 id="add-a-data-source-tab" tabindex="-1">Add a data source tab <a class="header-anchor" href="#add-a-data-source-tab" aria-label="Permalink to &quot;Add a data source tab&quot;">​</a></h2><ol><li>Open the sheet. At the end of the tab bar, click the arrow next to <strong>+</strong> (<strong>More tab types</strong>) and select <strong>Connect data source (SQL)…</strong>.</li><li>In <strong>Select data source</strong>, choose a connection your workspace already has and click <strong>Select</strong>. To add one, click <strong>New connection</strong> and continue below.</li><li>In <strong>New data source connection</strong>, enter the <strong>Name</strong>, <strong>Host</strong>, <strong>Port</strong> (default <code>5432</code>), <strong>Database</strong>, <strong>Username</strong>, and <strong>Password</strong>.</li><li>Turn on <strong>Enable SSL</strong> if the database requires it.</li><li>Click <strong>Test connection</strong>. A message confirms <code>Connected to &lt;host&gt;</code>, or says why it couldn&#39;t connect.</li><li>Click <strong>Save</strong>.</li></ol><p>A new tab named after the connection opens. A database icon marks it as a data source tab.</p><p><img src="'+n+`" alt="New data source connection dialog with host, port, database, and Enable SSL fields"></p><h2 id="run-a-query" tabindex="-1">Run a query <a class="header-anchor" href="#run-a-query" aria-label="Permalink to &quot;Run a query&quot;">​</a></h2><ol><li><p>Open the data source tab.</p></li><li><p>Type a query in the SQL box, for example:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> region, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SUM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(amount) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> revenue</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GROUP BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> region</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> revenue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span></code></pre></div></li><li><p>Click <strong>Execute</strong>, or press <code>⌘+Enter</code> / <code>Ctrl+Enter</code>.</p></li></ol><p>The results fill the grid. The first row holds the column names, and the status line shows the row count and time, such as <code>42 rows in 118ms</code>. A result that hit the limit says <code>(truncated)</code>.</p><p>Results don&#39;t refresh on their own. Click <strong>Execute</strong> again for fresh data.</p><p><img src="`+i+'" alt="Data source tab with a SQL query, the Execute button, and a results grid"></p><h2 id="use-the-results-in-a-sheet" tabindex="-1">Use the results in a sheet <a class="header-anchor" href="#use-the-results-in-a-sheet" aria-label="Permalink to &quot;Use the results in a sheet&quot;">​</a></h2><p>The results grid is read-only: you can select and copy cells, but not edit, sort, or filter them. Shape the data in SQL instead.</p><p>To build on the results:</p><ol><li>Select the cells in the results grid and press <code>⌘+C</code> / <code>Ctrl+C</code>.</li><li>Open a sheet tab, click the first cell, and press <code>⌘+V</code> / <code>Ctrl+V</code>.</li></ol><p>A formula in another tab can&#39;t read a data source tab. A reference such as <code>=Sales!A1</code> returns an empty value.</p><h2 id="edit-or-delete-a-connection" tabindex="-1">Edit or delete a connection <a class="header-anchor" href="#edit-or-delete-a-connection" aria-label="Permalink to &quot;Edit or delete a connection&quot;">​</a></h2><ol><li>In the workspace sidebar, click <strong>Data sources</strong>.</li><li>Find the connection and open its row menu (<strong>⋯</strong>).</li><li>Select <strong>Test connection</strong>, <strong>Edit</strong>, or <strong>Delete</strong>.</li></ol><p>In <strong>Edit data source</strong>, leave <strong>Password</strong> blank to keep the current one, then click <strong>Save changes</strong>. To add a connection from this page, click <strong>New data source</strong>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Delete</strong> removes the connection right away, with no confirmation, for everyone in the workspace.</p></div><h2 id="what-is-saved-in-the-document" tabindex="-1">What is saved in the document <a class="header-anchor" href="#what-is-saved-in-the-document" aria-label="Permalink to &quot;What is saved in the document&quot;">​</a></h2><ul><li>The query text is saved on the tab, so collaborators see it.</li><li>The results are not saved. Each person sees an empty grid until they click <strong>Execute</strong>.</li><li>Only the latest query for a tab is kept.</li></ul><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>PostgreSQL is the only database you can connect from the app.</li><li>A query that contains a word such as <code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>, <code>DROP</code>, <code>CREATE</code>, or <code>ALTER</code> anywhere, even inside a quoted string, is refused with <code>Forbidden keyword: …</code>.</li><li>Running more than one statement is refused with <code>Multiple statements are not allowed</code>.</li><li>Conditional formatting and data validation aren&#39;t available on data source tabs.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/lakehouse.html">Lakehouse tables</a> to read Iceberg or Delta Lake tables from object storage.</li><li><a href="/docs/collaborate/workspaces.html">Workspaces</a> to see who can use a shared connection.</li><li><a href="/docs/start/troubleshooting.html#only-select-queries-are-allowed">Troubleshooting</a> if a query fails with <code>Only SELECT queries are allowed</code>.</li></ul>',27)])])}const b=t(r,[["render",l]]);export{k as __pageData,b as default};
